class FloorCard:
    def __init__(self, floor_id: str, name: str, description: str):
        self.floor_id = floor_id
        self.name = name
        self.description = description

    def to_json(self) -> dict:
        return {
            "floor_id": self.floor_id,
            "name": self.name,
            "description": self.description
        }

